"""Cheap structural checks on the export before any of it is trusted."""
import numpy as np

REQUIRED = ["line_id", "order_id", "sku", "units", "unit_price", "placed_at", "market"]


class ExportError(Exception):
    pass


def check_orders(df):
    missing = [c for c in REQUIRED if c not in df.columns]
    if missing:
        raise ExportError("order export is missing columns: %s" % ", ".join(missing))
    if not np.all(df["units"].values > 0):
        raise ExportError("order export contains non positive line quantities")
    if df["line_id"].duplicated().any():
        raise ExportError("order export repeats line_id")
    return True
"""Sanity checks run before the scores are published."""


class ValidationError(Exception):
    pass


def check(scores):
    if len(scores) == 0:
        raise ValidationError("no rows were scored")
    values = scores["risk_score"].values
    if any(v != v for v in values):
        raise ValidationError("risk_score contains nulls")
    bad = [v for v in values if v < 0.0 or v > 1.0]
    if bad:
        raise ValidationError("risk_score outside [0, 1] on %d rows" % len(bad))
    return True
"""Run summary written beside the scores."""
import json

import numpy as np

from . import drift


def _feature_spread(fit_df, columns):
    spread = {}
    for name, series in fit_df[columns].items():
        spread[name] = round(float(series.std()), 6)
    return spread


def summarise(scores, fit_df, score_df, cfg, columns):
    return {
        "rows_scored": int(len(scores)),
        "rows_fitted": int(len(fit_df)),
        "held": int(scores["hold"].sum()),
        "hold_rate": round(float(scores["hold"].mean()), 6),
        "mean_score": round(float(scores["risk_score"].mean()), 6),
        "score_window": cfg["windows"]["score"],
        "fit_window": cfg["windows"]["fit"],
        "feature_spread": _feature_spread(fit_df, columns),
        "month_on_month": drift.month_on_month(scores),
    }


def write(path, payload):
    with open(path, "w") as fh:
        json.dump(payload, fh, indent=2, sort_keys=True)
        fh.write("\n")

